use super::helpers::compile_ok;

#[test] fn prop_getter_compiles() { compile_ok("IDENTIFICATION DIVISION.\nCLASS-ID. P1.\nOBJECT.\nMETHOD-ID. GET-A PROPERTY GET.\nPROCEDURE DIVISION RETURNING R.\n    MOVE 1 TO R.\nEND METHOD GET-A.\nEND OBJECT.\nEND CLASS P1."); }
#[test] fn prop_setter_compiles() { compile_ok("IDENTIFICATION DIVISION.\nCLASS-ID. P2.\nOBJECT.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 A PIC 9.\nMETHOD-ID. SET-A PROPERTY SET.\nPROCEDURE DIVISION USING I.\n    MOVE I TO A.\nEND METHOD SET-A.\nEND OBJECT.\nEND CLASS P2."); }
#[test] fn prop_get_set_pair_compiles() { compile_ok("IDENTIFICATION DIVISION.\nCLASS-ID. P3.\nOBJECT.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 A PIC 9.\nMETHOD-ID. GET-A PROPERTY GET.\nPROCEDURE DIVISION RETURNING R.\n    MOVE A TO R.\nEND METHOD GET-A.\nMETHOD-ID. SET-A PROPERTY SET.\nPROCEDURE DIVISION USING I.\n    MOVE I TO A.\nEND METHOD SET-A.\nEND OBJECT.\nEND CLASS P3."); }
