#[test] fn prop_numeric_property_compiles() { compile_ok("IDENTIFICATION DIVISION.\nCLASS-ID. P5.\nOBJECT.\nDATA DIVISION.\nWORKING-STORAGE SECTION.\n01 V PIC 9(5).\nMETHOD-ID. SET-V PROPERTY SET.\nPROCEDURE DIVISION USING I.\n    MOVE I TO V.\nEND METHOD SET-V.\nEND OBJECT.\nEND CLASS P5."); }
