#[test] fn prop_property_get_override_chain_compiles() { compile_ok("IDENTIFICATION DIVISION.\nCLASS-ID. P15 INHERITS FROM P14.\nOBJECT.\nMETHOD-ID. GET-Z PROPERTY GET.\nPROCEDURE DIVISION RETURNING R.\n    MOVE 1 TO R.\nEND METHOD GET-Z.\nEND OBJECT.\nEND CLASS P15."); }
